import { readFileSync, writeFileSync } from "node:fs";
const names = {
  publicProxy: "public_proxy.py",
  publicBridge: "public_bridge.py",
};
writeFileSync(
  new URL("../packages/media/public-proxy.ts", import.meta.url),
  "// Generated by scripts/sync-public-proxy.mjs.\n" +
    Object.entries(names)
      .map(
        ([name, file]) =>
          `export const ${name} = ${JSON.stringify(readFileSync(new URL("../packages/media/" + file, import.meta.url), "utf8"))};\n`,
      )
      .join(""),
);
